//----- (10008620) --------------------------------------------------------
int AAS_RemoveClusterAreas()
{
  int result; // eax
  int i; // ecx

  result = aasworld.numareas;
  i = 1;
  if ( aasworld.numareas > 1 )
  {
    result = 28;
    do
    {
      ++i;
      *(_DWORD *)((char *)aasworld.areasettings + result + 12) = 0;
      result += 28;
    }
    while ( i < aasworld.numareas );
  }
  return result;
}

//----- (10008660) --------------------------------------------------------
int __cdecl AAS_UpdatePortal(int areanum, int clusternum)
{
  int portalnum; // eax
  aas_portal_t *portal; // edx
  aas_cluster_t *cluster; // ecx

  for ( portalnum = 1; portalnum < aasworld.numportals; ++portalnum )
  {
    if ( aasworld.portals[portalnum].areanum == areanum )
      break;
  }
  if ( portalnum == aasworld.numportals )
  {
    AAS_Error("no portal of area %d", areanum);
    return 1;
  }
  portal = &aasworld.portals[portalnum];
  if ( portal->frontcluster == clusternum )
    return 1;
  if ( portal->backcluster == clusternum )
    return 1;
  if ( !portal->frontcluster )
  {
    portal->frontcluster = clusternum;
  }
  else if ( !portal->backcluster )
  {
    portal->backcluster = clusternum;
  }
  else
  {
    Log_Write("portal using area %d is seperating more than two clusters",
              areanum);
    aasworld.areasettings[areanum].contents &= ~8u;
    return 0;
  }
  if ( aasworld.portalindexsize >= 0x10000 )
  {
    AAS_Error("AAS_MAX_PORTALINDEXSIZE");
    return 1;
  }
  aasworld.areasettings[areanum].cluster = -portalnum;
  cluster = &aasworld.clusters[clusternum];
  aasworld.portalindex[cluster->firstportal + cluster->numreachabilityareas] = portalnum;
  ++aasworld.portalindexsize;
  ++cluster->numreachabilityareas;
  return 1;
}

//----- (100087E0) --------------------------------------------------------
int __cdecl AAS_FloodClusterAreas_r(int areanum, int clusternum)
{
  int i; // ebp
  aas_area_t *area; // esi
  int facenum; // rax
  int v10; // eax
  aas_face_t *face; // ecx
  int v12; // ecx
  int v14; // esi
  int v15; // eax

  if ( areanum <= 0 || areanum >= aasworld.numareas )
  {
    AAS_Error("AAS_FloodClusterAreas_r: areanum out of range");
    return 0;
  }
  if ( aasworld.areasettings[areanum].cluster > 0 )
  {
    if ( aasworld.areasettings[areanum].cluster != clusternum )
    {
      Log_Write("cluster %d touched cluster %d at area %d", clusternum,
                aasworld.areasettings[areanum].cluster, areanum);
      return 0;
    }
  }
  else
  {
    if ( (aasworld.areasettings[areanum].contents & 8) != 0 )
      return AAS_UpdatePortal(areanum, clusternum);
  aasworld.areasettings[areanum].cluster = clusternum;
  aasworld.areasettings[areanum].clusterareanum = (aasworld.clusters[clusternum].numareas)++;
  area = &aasworld.areas[areanum];
  for ( i = 0; i < area->numfaces; i++ )
  {
    facenum = aasworld.faceindex[i + area->firstface];
    facenum = abs(facenum);
    v10 = aasworld.faces[facenum].frontarea;
    face = &aasworld.faces[facenum];
    if ( v10 == areanum )
    {
      v12 = face->backarea;
      if ( v12 && !AAS_FloodClusterAreas_r(v12, clusternum) )
        return 0;
    }
    else if ( v10 && !AAS_FloodClusterAreas_r(v10, clusternum) )
    {
      return 0;
    }
  }
  for ( v14 = 0; v14 < aasworld.areasettings[areanum].numreachableareas; v14++ )
  {
    v15 = aasworld.reachability[v14 + aasworld.areasettings[areanum].firstreachablearea].areanum;
    if ( v15 && !AAS_FloodClusterAreas_r(v15, clusternum) )
      return 0;
  }
  }
  return 1;
}

//----- (100089E0) --------------------------------------------------------
int __cdecl AAS_FloodClusterReachabilities(int clusternum)
{
  int i;
  int j;
  int areanum;

  for ( i = 1; i < aasworld.numareas; ++i )
  {
    if ( aasworld.areasettings[i].cluster )
      continue;
    if ( aasworld.areasettings[i].contents & 8 )
      continue;
    for ( j = 0; j < aasworld.areasettings[i].numreachableareas; ++j )
    {
      areanum = aasworld.reachability[aasworld.areasettings[i].firstreachablearea + j].areanum;
      if ( aasworld.areasettings[areanum].contents & 8 )
        continue;
      if ( aasworld.areasettings[areanum].cluster )
      {
        if ( !AAS_FloodClusterAreas_r(i, clusternum) )
          return 0;
        i = 0;
        break;
      }
    }
  }
  return 1;
}

//----- (10008AC0) --------------------------------------------------------
void __cdecl AAS_NumberClusterPortals(int clusternum)
{
  int i;
  int portalnum;
  aas_cluster_t *cluster;
  aas_portal_t *portal;

  cluster = &aasworld.clusters[clusternum];
  for ( i = 0; i < cluster->numreachabilityareas; i++ )
  {
    portalnum = aasworld.portalindex[cluster->firstportal + i];
    portal = &aasworld.portals[portalnum];
    if ( portal->frontcluster == clusternum )
      portal->clusterareanum[0] = cluster->numareas++;
    else
      portal->clusterareanum[1] = cluster->numareas++;
  }
}

//----- (10008B40) --------------------------------------------------------
int AAS_FindClusters()
{
  int i; // ebx
  aas_cluster_t *cluster; // esi

  AAS_RemoveClusterAreas();
  for ( i = 1; i < aasworld.numareas; i++ )
  {
    if ( aasworld.areasettings[i].cluster == 0 && (aasworld.areasettings[i].contents & 8) == 0 )
    {
      if ( aasworld.numclusters >= 0x10000 )
      {
        AAS_Error("AAS_MAX_CLUSTERS");
        return 0;
      }
      cluster = &aasworld.clusters[aasworld.numclusters];
      cluster->numareas = 0;
      cluster->firstportal = aasworld.portalindexsize;
      cluster->numreachabilityareas = 0;
      if ( !AAS_FloodClusterAreas_r(i, aasworld.numclusters) || !AAS_FloodClusterReachabilities(aasworld.numclusters) )
        return 0;
      AAS_NumberClusterPortals(aasworld.numclusters);
      Log_Write("cluster %d has %d areas", aasworld.numclusters, cluster->numareas);
      aasworld.numclusters++;
    }
  }
  return 1;
}

//----- (10008C80) --------------------------------------------------------
void AAS_CreatePortals()
{
  int i;
  aas_portal_t *portal;

  for ( i = 1; i < aasworld.numareas; i++ )
  {
    if ( (aasworld.areasettings[i].contents & 8) != 0 )
    {
      if ( aasworld.numportals >= 0x10000 )
      {
        AAS_Error("AAS_MAX_PORTALS");
        return;
      }
      portal = &aasworld.portals[aasworld.numportals];
      portal->areanum = i;
      portal->frontcluster = 0;
      portal->backcluster = 0;
      Log_Write("portal %d: area %d", aasworld.numportals, i);
      aasworld.numportals++;
    }
  }
}

//----- (10008D40) --------------------------------------------------------
void __cdecl AAS_ConnectedAreas_r(int *areanums, int numareas, int *connectedareas, int curarea)
{
  int i, j, otherareanum, facenum;
  aas_area_t *area;
  aas_face_t *face;

  connectedareas[curarea] = 1;
  area = &aasworld.areas[areanums[curarea]];
  for ( i = 0; i < area->numfaces; i++ )
  {
    facenum = abs(aasworld.faceindex[area->firstface + i]);
    face = &aasworld.faces[facenum];
    if ( (face->faceflags & 1) != 0 )
      continue;
    if ( face->frontarea != areanums[curarea] )
      otherareanum = face->frontarea;
    else
      otherareanum = face->backarea;
    for ( j = 0; j < numareas; j++ )
    {
      if ( areanums[j] == otherareanum )
        break;
    }
    if ( j == numareas )
      continue;
    if ( connectedareas[j] )
      continue;
    AAS_ConnectedAreas_r(areanums, numareas, connectedareas, j);
  }
}

//----- (10008E20) --------------------------------------------------------
qboolean __cdecl AAS_ConnectedAreas(_DWORD *areanums, int numareas)
{
  int connectedareas[128]; // [esp+8h] [ebp-200h] BYREF
  int i;

  memset(connectedareas, 0, sizeof(connectedareas));
  if ( numareas < 1 )
    return 0;
  if ( numareas == 1 )
    return 1;
  AAS_ConnectedAreas_r(areanums, numareas, connectedareas, 0);
  for ( i = 0; i < numareas; i++ )
  {
    if ( !connectedareas[i] )
      return 0;
  }
  return 1;
}
// 10008E6A: conditional instruction was optimized away because %arg_4.4>=2

//----- (10008EB0) --------------------------------------------------------
int __cdecl AAS_FloodAreas_r(int *areanum, int cluster, int done)
{
  aas_area_t *area;
  aas_face_t *face;
  int presencetype;
  int i, j, nextareanum;

  areanum[cluster++] = done;
  area = &aasworld.areas[done];
  presencetype = aasworld.areasettings[done].presencetype;
  for ( i = 0; i < area->numfaces; i++ )
  {
    face = &aasworld.faces[abs(aasworld.faceindex[area->firstface + i])];
    if ( (face->faceflags & 1) != 0 )
      continue;
    if ( face->frontarea != done )
      nextareanum = face->frontarea;
    else
      nextareanum = face->backarea;
    if ( (~aasworld.areasettings[nextareanum].presencetype & presencetype) == 0
      || (~presencetype & aasworld.areasettings[nextareanum].presencetype) != 0 )
    {
      continue;
    }
    for ( j = 0; j < cluster; j++ )
    {
      if ( nextareanum == areanum[j] )
        break;
    }
    if ( j != cluster )
      continue;
    if ( cluster >= 128 )
    {
      AAS_Error("MAX_PORTALAREAS");
      break;
    }
    cluster = AAS_FloodAreas_r(areanum, cluster, nextareanum);
  }
  return cluster;
}

//----- (10008FF0) --------------------------------------------------------
int __cdecl AAS_CheckAreaForPossiblePortals(int areanum)
{
  int i;
  int j;
  int k;
  int fen;
  int ben;
  int frontedgenum;
  int backedgenum;
  int facenum;
  int areanums[128];
  int numareas;
  int otherareanum;
  int numareafrontfaces[128];
  int numareabackfaces[128];
  int frontfacenums[128];
  int backfacenums[128];
  int numfrontfaces;
  int numbackfaces;
  int frontareanums[128];
  int backareanums[128];
  int numfrontareas;
  int numbackareas;
  int frontplanenum;
  int backplanenum;
  int faceplanenum;
  aas_area_t *area;
  aas_face_t *frontface;
  aas_face_t *backface;
  aas_face_t *face;

  if ( aasworld.areasettings[areanum].contents & 8 )
    return 0;
  if ( !(aasworld.areasettings[areanum].areaflags & 1) )
    return 0;
  memset(numareafrontfaces, 0, sizeof(numareafrontfaces));
  memset(numareabackfaces, 0, sizeof(numareabackfaces));
  numareas = numfrontfaces = numbackfaces = 0;
  numfrontareas = numbackareas = 0;
  frontplanenum = backplanenum = -1;
  numareas = AAS_FloodAreas_r(areanums, 0, areanum);
  for ( i = 0; i < numareas; i++ )
  {
    area = &aasworld.areas[areanums[i]];
    for ( j = 0; j < area->numfaces; j++ )
    {
      facenum = abs(aasworld.faceindex[area->firstface + j]);
      face = &aasworld.faces[facenum];
      if ( face->faceflags & 1 )
        continue;
      for ( k = 0; k < numareas; k++ )
      {
        if ( k == i )
          continue;
        if ( face->frontarea == areanums[k] || face->backarea == areanums[k] )
          break;
      }
      if ( k != numareas )
        continue;
      if ( face->frontarea == areanums[i] )
        otherareanum = face->backarea;
      else
        otherareanum = face->frontarea;
      if ( aasworld.areasettings[otherareanum].contents & 8 )
        return 0;
      faceplanenum = face->planenum & ~1;
      if ( frontplanenum < 0 || faceplanenum == frontplanenum )
      {
        frontplanenum = faceplanenum;
        frontfacenums[numfrontfaces++] = facenum;
        for ( k = 0; k < numfrontareas; k++ )
        {
          if ( frontareanums[k] == otherareanum )
            break;
        }
        if ( k == numfrontareas )
          frontareanums[numfrontareas++] = otherareanum;
        numareafrontfaces[i]++;
      }
      else if ( backplanenum < 0 || faceplanenum == backplanenum )
      {
        backplanenum = faceplanenum;
        backfacenums[numbackfaces++] = facenum;
        for ( k = 0; k < numbackareas; k++ )
        {
          if ( backareanums[k] == otherareanum )
            break;
        }
        if ( k == numbackareas )
          backareanums[numbackareas++] = otherareanum;
        numareabackfaces[i]++;
      }
      else
      {
        return 0;
      }
    }
  }
  for ( i = 0; i < numareas; i++ )
  {
    if ( !numareafrontfaces[i] || !numareabackfaces[i] )
      return 0;
  }
  if ( !AAS_ConnectedAreas(frontareanums, numfrontareas) )
    return 0;
  if ( !AAS_ConnectedAreas(backareanums, numbackareas) )
    return 0;
  for ( i = 0; i < numfrontfaces; i++ )
  {
    frontface = &aasworld.faces[frontfacenums[i]];
    for ( fen = 0; fen < frontface->numedges; fen++ )
    {
      frontedgenum = abs(aasworld.edgeindex[frontface->firstedge + fen]);
      for ( j = 0; j < numbackfaces; j++ )
      {
        backface = &aasworld.faces[backfacenums[j]];
        for ( ben = 0; ben < backface->numedges; ben++ )
        {
          backedgenum = abs(aasworld.edgeindex[backface->firstedge + ben]);
          if ( frontedgenum == backedgenum )
            break;
        }
        if ( ben != backface->numedges )
          break;
      }
      if ( j != numbackfaces )
        break;
    }
    if ( fen != frontface->numedges )
      break;
  }
  if ( i != numfrontfaces )
    return 0;
  for ( i = 0; i < numareas; i++ )
  {
    aasworld.areasettings[areanums[i]].contents |= 8u;
    aasworld.areasettings[areanums[i]].contents |= 0x20u;
    Log_Write("possible portal: %d", areanums[i]);
  }
  return numareas;
}

//----- (10009570) --------------------------------------------------------
int AAS_FindPossiblePortals()
{
  int i; // esi
  int numpossibleportals; // edi

  i = 1;
  for ( numpossibleportals = 0; i < aasworld.numareas; ++i )
    numpossibleportals += AAS_CheckAreaForPossiblePortals(i);
  return botimport.Print(PRT_MESSAGE, "\r%6d possible portals\n", numpossibleportals);
}

//----- (100095C0) --------------------------------------------------------
void AAS_RemoveAllPortals()
{
  int i;

  for ( i = 1; i < aasworld.numareas; i++ )
  {
    aasworld.areasettings[i].contents &= ~8u;
  }
}

//----- (10009610) --------------------------------------------------------
int AAS_TestPortals()
{
  int i;
  aas_portal_t *portal;

  for ( i = 1; i < aasworld.numportals; i++ )
  {
    portal = &((aas_portal_t *)aasworld.portals)[i];
    if ( !portal->frontcluster )
    {
      ((aas_areasettings_t *)aasworld.areasettings)[portal->areanum].contents &= ~8u;
      Log_Write("portal area %d has no front cluster\n", portal->areanum);
      return 0;
    }
    if ( !portal->backcluster )
    {
      ((aas_areasettings_t *)aasworld.areasettings)[portal->areanum].contents &= ~8u;
      Log_Write("portal area %d has no back cluster\n", portal->areanum);
      return 0;
    }
  }
  return 1;
}

//----- (100096E0) --------------------------------------------------------
void AAS_InitClustering()
{
  if ( !aasworld.loaded )
    return;
  if ( aasworld.numclusters >= 1
    && !(int)LibVarGetValue("forceclustering")
    && !(int)LibVarGetValue("forcereachability") )
  {
    return;
  }
  AAS_RemoveAllPortals();
  AAS_RemoveClusterAreas();
  AAS_FindPossiblePortals();
  if ( aasworld.portals )
    FreeMemory(aasworld.portals);
  aasworld.portals = GetClearedMemory(1310720);
  if ( aasworld.portalindex )
    FreeMemory(aasworld.portalindex);
  aasworld.portalindex = (int *)GetClearedMemory(0x40000);
  if ( aasworld.clusters )
    FreeMemory(aasworld.clusters);
  aasworld.clusters = GetClearedMemory(786432);
  while ( 1 )
  {
    aasworld.numportals = 1;
    aasworld.portalindexsize = 0;
    aasworld.numclusters = 1;
    AAS_CreatePortals();
    if ( !AAS_FindClusters() )
      continue;
    if ( AAS_TestPortals() )
      break;
  }
  aasworld.savefile = 1;
  botimport.Print(PRT_MESSAGE, "\r%6d portals created\n", aasworld.numportals);
  botimport.Print(PRT_MESSAGE, "\r%6d clusters created\n", aasworld.numclusters);
}

//----- (10009860) --------------------------------------------------------
int AAS_ClearShownDebugLines()
{
  int i; // esi
  int result; // eax

  for ( i = 0; i < 256; ++i )
  {
    result = debuglines[i];
    if ( result )
    {
      result = botimport.DebugLineShow(result, 0, 0, -1);
      debuglinevisible[i] = 0;
    }
  }
  return result;
}

//----- (100098B0) --------------------------------------------------------
int __cdecl AAS_DebugLine(vec3_t start, vec3_t end, int color)
{
  int line; // esi
  int v4; // eax
  int result; // eax

  line = 0;
  while ( 1 )
  {
    if ( !debuglines[line] )
    {
      debuglines[line] = botimport.DebugLineCreate();
      v4 = numdebuglines + 1;
      debuglinevisible[line] = 0;
      numdebuglines = v4;
    }
    result = debuglinevisible[line];
    if ( !result )
      break;
    if ( ++line >= 256 )
      return result;
  }
  result = botimport.DebugLineShow(debuglines[line], start, end, color);
  debuglinevisible[line] = 1;
  return result;
}

//----- (10009950) --------------------------------------------------------
int __cdecl AAS_DrawPermanentCross(vec3_t origin, float size, int color)
{
  int i;
  int debugline;
  int result;
  vec3_t start, end;

  for ( i = 0; i < 3; i++ )
  {
    VectorCopy(origin, start);
    start[i] += size;
    VectorCopy(origin, end);
    end[i] -= size;
    AAS_DebugLine(start, end, color);
    debugline = botimport.DebugLineCreate();
    result = botimport.DebugLineShow(debugline, start, end, color);
  }
  return result;
}

//----- (10009A10) --------------------------------------------------------
/* AAS_DrawPlaneCross — plane-projection debug "X" visualiser (Q3
 * be_aas_debug.c, verbatim).  Builds four corners of a 12x12 square around the
 * hit point in the two transverse axes (±6; the 6.0 float is .rdata 0x1005804c),
 * projects each onto the plane along axis n0=type%3, then draws the two
 * diagonals via botimport.DebugLineShow using line-IDs from the shared
 * debuglines/debuglinevisible/numdebuglines pool.
 *
 * This is the EXACT Q3 source form; byte-identical to the original at 0x10009A10
 * under the MSVC6 oracle (a prior reconstruction had the projection operands and
 * loop guard reordered, which diverged — see the asmdiff_workflow "restore the
 * Q3 form" lever).
 *
 * DEAD in shipped Gladiator (no .text caller); preserved by /INCREMENTAL.
 * External linkage (NOT static): cl /O2 drops an unreferenced static, but the
 * original emitted this as a file-scope function that /INCREMENTAL then kept —
 * so external linkage is the faithful form and lets the oracle audit it. */
void AAS_DrawPlaneCross(vec3_t point, vec3_t normal, float dist, int type, int color)
{
  int    n0, n1, n2, j, line, lines[2];
  vec3_t start1, end1, start2, end2;

  //make a cross in the hit plane at the hit point
  VectorCopy(point, start1);
  VectorCopy(point, end1);
  VectorCopy(point, start2);
  VectorCopy(point, end2);

  n0 = type % 3;
  n1 = (type + 1) % 3;
  n2 = (type + 2) % 3;
  start1[n1] -= 6;
  start1[n2] -= 6;
  end1[n1] += 6;
  end1[n2] += 6;
  start2[n1] += 6;
  start2[n2] -= 6;
  end2[n1] -= 6;
  end2[n2] += 6;

  start1[n0] = (dist - (start1[n1] * normal[n1] + start1[n2] * normal[n2])) / normal[n0];
  end1[n0]   = (dist - (end1[n1] * normal[n1] + end1[n2] * normal[n2])) / normal[n0];
  start2[n0] = (dist - (start2[n1] * normal[n1] + start2[n2] * normal[n2])) / normal[n0];
  end2[n0]   = (dist - (end2[n1] * normal[n1] + end2[n2] * normal[n2])) / normal[n0];

  for (j = 0, line = 0; j < 2 && line < 256; line++)
  {
    if (!debuglines[line])
    {
      debuglines[line] = botimport.DebugLineCreate();
      lines[j++] = debuglines[line];
      debuglinevisible[line] = 1;
      numdebuglines++;
    }
    else if (!debuglinevisible[line])
    {
      lines[j++] = debuglines[line];
      debuglinevisible[line] = 1;
    }
  }
  botimport.DebugLineShow(lines[0], start1, end1, color);
  botimport.DebugLineShow(lines[1], start2, end2, color);
}

//----- (10009CB0) --------------------------------------------------------
/* AAS_ShowBoundingBox — DEAD debug-cube draw helper.  Restored from
 * objdump@0x10009CB0 (131 lines).  Identity: Q3's AAS_ShowBoundingBox
 * (be_aas_debug.c) — same 8-corner cube, 3-line-ID cycle, and
 * top/bottom/vertical edge-draw loop.  NOTE: the .text reads the 2nd
 * stack param for the top (maxs) corners and the 3rd for the bottom
 * (mins) corners — the reverse of Q3's (origin, mins, maxs) prototype —
 * so the param order here is kept as decompiled to stay byte-faithful.
 * Draws an AABB at origin with
 * mins/maxs offsets as a wireframe cube of color 0xF2F2F0F0 using the
 * shared debuglines line-ID slot table — but only retains THREE
 * line IDs across all 12 edges, so the bottom-quad / top-quad /
 * vertical edges visible at any moment cycle through which 3 of the
 * 12 are present.  Almost certainly a development-time visualization
 * (e.g., a "flicker the entity bbox so it's not too noisy in the
 * debug view" toggle).
 *
 * Signature (cdecl, 3 vec3 args):
 *   void AAS_ShowBoundingBox(vec3_t origin, vec3_t mins_offset, vec3_t maxs_offset)
 *
 * Geometry (verified field-by-field from the .text FPU schedule):
 *   X1 = origin[0] + mins[0]   X4 = origin[0] + maxs[0]
 *   X2 = origin[1] + mins[1]   X5 = origin[1] + maxs[1]
 *   X3 = origin[2] + mins[2]   X6 = origin[2] + maxs[2]
 *
 *   bottom_corners[4] @ [ebp-0x60..0x34]:   z = X3 (= origin.z + mins.z)
 *     [0] = (X1, X2, X3)   SW
 *     [1] = (X4, X2, X3)   SE
 *     [2] = (X4, X5, X3)   NE
 *     [3] = (X1, X5, X3)   NW
 *   top_corners[4]    @ [ebp-0x30..0x04]:   z = X6 (= origin.z + maxs.z)
 *     (memcpy from bottom, then a 4×stride-12 fst loop overwrites z
 *     of each copy with X6 — Mr. Elusive's verbatim trick to build
 *     "same XY, different Z" by patching the third float in place.)
 *
 * Per outer iteration i in [1..4]:
 *   - bi_DebugLineShow(line_ids[0], &bot[i-1],         &bot[i & 3],   0xF2F2F0F0)
 *   - bi_DebugLineShow(line_ids[1], &top[i-1],         &top[i & 3],   0xF2F2F0F0)
 *   - bi_DebugLineShow(line_ids[2], &bot[i-1],         &top[i-1],     0xF2F2F0F0)
 *   = 12 line draws covering all 12 cube edges, but with only
 *     3 line IDs cycled (each ID's last assignment wins on screen).
 *
 * Line-ID allocation (front of function) inlines a private copy of
 * AAS_DebugLine's slot scan: it walks debuglines[0..255] looking
 * for either an empty slot (calls bi_DebugLineCreate, bumps
 * numdebuglines free counter) or an existing-but-unused slot,
 * markes it in-use via debuglinevisible[slot] = 1, and stashes 3 IDs
 * into a local int[3].
 *
 * NOTE: The .text writes the outer-loop counter `i` to scratch slot
 * [esp+0x80] (= the function's arg0 stack slot — overwritten because
 * arg0/1/2 were already loaded into eax/edx/ecx).  Restoration
 * uses a real local instead.
 *
 * Thunks: ds:0x10063FFC = bi_DebugLineCreate
 *         ds:0x10064004 = bi_DebugLineShow
 * Globals: debuglines[256] = line-ID slot table
 *          debuglinevisible[256] = per-slot in-use flag
 *          numdebuglines      = free counter
 *
 * DEAD in Gladiator — no live caller.  Preserved by /INCREMENTAL. */
void __cdecl AAS_ShowBoundingBox(vec3_t origin, vec3_t mins, vec3_t maxs)
{
  vec3_t bboxcorners[8];
  int lines[3];
  int i, j, line;

  VectorAdd(origin, maxs, bboxcorners[0]);
  bboxcorners[1][0] = origin[0] + mins[0];
  bboxcorners[1][1] = origin[1] + maxs[1];
  bboxcorners[1][2] = origin[2] + maxs[2];
  bboxcorners[2][0] = origin[0] + mins[0];
  bboxcorners[2][1] = origin[1] + mins[1];
  bboxcorners[2][2] = origin[2] + maxs[2];
  bboxcorners[3][0] = origin[0] + maxs[0];
  bboxcorners[3][1] = origin[1] + mins[1];
  bboxcorners[3][2] = origin[2] + maxs[2];
  memcpy(bboxcorners[4], bboxcorners[0], sizeof(vec3_t) * 4);
  for ( i = 0; i < 4; i++ )
    bboxcorners[4 + i][2] = origin[2] + mins[2];
  for ( i = 0; i < 4; i++ )
  {
    for ( j = 0, line = 0; j < 3 && line < 256; line++ )
    {
      if ( !debuglines[line] )
      {
        debuglines[line] = botimport.DebugLineCreate();
        lines[j++] = debuglines[line];
        debuglinevisible[line] = 1;
        numdebuglines++;
      }
      else if ( !debuglinevisible[line] )
      {
        lines[j++] = debuglines[line];
        debuglinevisible[line] = 1;
      }
    }
    botimport.DebugLineShow(lines[0], bboxcorners[i], bboxcorners[(i + 1) & 3], 0xF2F2F0F0);
    botimport.DebugLineShow(lines[1], bboxcorners[4 + i], bboxcorners[4 + ((i + 1) & 3)], 0xF2F2F0F0);
    botimport.DebugLineShow(lines[2], bboxcorners[i], bboxcorners[4 + i], 0xF2F2F0F0);
  }
}

//----- (10009ED0) --------------------------------------------------------
/* Restored (IDA-missed dead-code stub, /INCREMENTAL leftover).  Decoded
 * from objdump@10009ED0 (size 0x162 / 128 lines).  Identity: AAS_ShowFace
 * — given a face index, draws every edge of the face as a line with a
 * rotating 4-color debug palette, then draws a 20-unit normal arrow from
 * the face's first vertex along the face's plane normal in color
 * 0xF2F2F0F0.  Sibling of AAS_ShowArea@1000A0A0 (which calls AAS_DebugLine
 * per ground-face edge) but operates on a single face index directly.
 *
 * aasworld globals consulted (all already documented elsewhere):
 *   ds:0x1006691C  vertexes pool       (stride 12  = vec3)
 *   ds:0x10066924  planes pool         (stride 20  = normal[3] + dist + type)
 *   ds:0x10066928  numedges            (range-check bound)
 *   ds:0x1006692C  edges pool          (stride 8   = v0_idx, v1_idx)
 *   ds:0x10066934  edgeindex           (signed; abs = edge_idx)
 *   ds:0x10066938  numfaces            (range-check bound)
 *   ds:0x1006693C  faces pool          (stride 24  = planenum@0, numedges@8, firstedge@0xC)
 *
 * Color rotation (initial value 0xDCDDDEDF, then cycles 4 ways):
 *   0xDCDDDEDF → 0xF2F2F0F0 → 0xD0D1D2D3 → 0xF3F3F1F1 → (loop)
 * Decoded from the if/else/else chain at 10009F48-10009F7B which the
 * compiler obfuscated into a sub/neg/sbb/and/add bit-twiddle for the
 * fall-through branch — the algebra reduces to exactly the same 4-cycle.
 * Cleanest C expression is a 4-entry table and modulo step.
 *
 * Range warnings issued via bi_Print(PRT_ERROR, msg, idx) for facenum or edgenum
 * out of range (.rdata strings 0x1005AFE8="facenum %d out of range\\n",
 * 0x1005AFC8="edgenum %d out of range\\n").
 *
 * DEAD in shipped Gladiator (no .text caller; AAS_ShowArea draws
 * area-level wireframes via a different path).  Restored verbatim. */
void __cdecl AAS_ShowFace(int facenum)
{
  int i, color, edgenum;
  aas_edge_t *edge;
  aas_face_t *face;
  aas_plane_t *plane;
  vec3_t start, end;

  color = LINECOLOR_YELLOW;
  if ( facenum >= aasworld.numfaces )
    botimport.Print(PRT_ERROR, "facenum %d out of range\n", facenum);
  face = &aasworld.faces[facenum];
  for ( i = 0; i < face->numedges; i++ )
  {
    edgenum = abs(aasworld.edgeindex[face->firstedge + i]);
    if ( edgenum >= aasworld.numedges )
      botimport.Print(PRT_ERROR, "edgenum %d out of range\n", edgenum);
    edge = &aasworld.edges[edgenum];
    if ( color == LINECOLOR_RED )
      color = LINECOLOR_GREEN;
    else if ( color == LINECOLOR_GREEN )
      color = LINECOLOR_BLUE;
    else if ( color == LINECOLOR_BLUE )
      color = LINECOLOR_YELLOW;
    else
      color = LINECOLOR_RED;
    AAS_DebugLine(aasworld.vertexes[edge->v[0]], aasworld.vertexes[edge->v[1]], color);
  }
  plane = &aasworld.planes[face->planenum];
  edgenum = abs(aasworld.edgeindex[face->firstedge]);
  edge = &aasworld.edges[edgenum];
  VectorCopy(aasworld.vertexes[edge->v[0]], start);
  VectorMA(start, 20.0f, plane->normal, end);
  AAS_DebugLine(start, end, LINECOLOR_RED);
}

//----- (1000A0A0) --------------------------------------------------------
void __cdecl AAS_ShowArea(int areanum, int groundfacesonly)
{
  int areaedges[256];
  int numareaedges, i, j, n, color, line;
  int facenum, edgenum;
  aas_area_t *area;
  aas_face_t *face;
  aas_edge_t *edge;

  numareaedges = 0;
  color = 0;
  if ( areanum < 0 || areanum >= aasworld.numareas )
  {
    botimport.Print(PRT_ERROR, "area %d out of range [0, %d]\n", areanum, aasworld.numareas);
    return;
  }
  area = &aasworld.areas[areanum];
  for ( i = 0; i < area->numfaces; i++ )
  {
    facenum = abs(aasworld.faceindex[area->firstface + i]);
    if ( facenum >= aasworld.numfaces )
      botimport.Print(PRT_ERROR, "facenum %d out of range\n", facenum);
    face = &aasworld.faces[facenum];
    if ( groundfacesonly )
    {
      if ( (face->faceflags & 6) == 0 )
        continue;
    }
    for ( j = 0; j < face->numedges; j++ )
    {
      edgenum = abs(aasworld.edgeindex[face->firstedge + j]);
      if ( edgenum >= aasworld.numedges )
        botimport.Print(PRT_ERROR, "edgenum %d out of range\n", edgenum);
      for ( n = 0; n < numareaedges; n++ )
      {
        if ( areaedges[n] == edgenum )
          break;
      }
      if ( n == numareaedges && numareaedges < 256 )
        areaedges[numareaedges++] = edgenum;
    }
  }
  for ( n = 0; n < numareaedges; n++ )
  {
    for ( line = 0; line < 256; line++ )
    {
      if ( !debuglines[line] )
      {
        debuglines[line] = botimport.DebugLineCreate();
        debuglinevisible[line] = 0;
        numdebuglines++;
      }
      if ( !debuglinevisible[line] )
        break;
    }
    if ( line >= 256 )
      return;
    edge = &aasworld.edges[areaedges[n]];
    if ( color == LINECOLOR_RED )
      color = LINECOLOR_BLUE;
    else if ( color == LINECOLOR_BLUE )
      color = LINECOLOR_GREEN;
    else if ( color == LINECOLOR_GREEN )
      color = LINECOLOR_YELLOW;
    else
      color = LINECOLOR_RED;
    botimport.DebugLineShow(
      debuglines[line],
      aasworld.vertexes[edge->v[0]],
      aasworld.vertexes[edge->v[1]],
      color);
    debuglinevisible[line] = 1;
  }
}
// 1000A228: conditional instruction was optimized away because esi.4<100

//----- (1000A370) --------------------------------------------------------
/*
 * AAS_DrawCross — draws a 3D cross at `origin` with arm length `size` in
 * the given color.  Renamed from sub_1000A370 / AAS_AddBBoxFaceEdges.
 * Structural match: ioq3 code/botlib/be_aas_debug.c:525 — three line
 * segments along each axis, each spanning [origin-size, origin+size].
 */
void __cdecl AAS_DrawCross(vec3_t origin, float size, int color)
{
  int i;
  vec3_t start, end;

  for ( i = 0; i < 3; i++ )
  {
    VectorCopy(origin, start);
    start[i] += size;
    VectorCopy(origin, end);
    end[i] -= size;
    AAS_DebugLine(start, end, color);
  }
}

