  if ( aasworld.edgeindex )
    FreeMemory(aasworld.edgeindex);
  aasworld.edgeindex = 0;
  aasworld.numfaces = 0;
  if ( aasworld.faces )
    FreeMemory(aasworld.faces);
  aasworld.faces = 0;
  aasworld.faceindexsize = 0;
  if ( aasworld.faceindex )
    FreeMemory(aasworld.faceindex);
  aasworld.faceindex = 0;
