//----- (1000DDA0) --------------------------------------------------------
/* Restored from original MSVC source (0x1000DDA0).  Q3 equivalent:
 * AAS_PresenceTypeBoundingBox in be_aas_sample.c.  Verified against binary
 * at 0x1000DDC2-0x1000DE32: 0xC1800000 = -16.0f, 0x41800000 = +16.0f.
 * Q2 player bbox is 32x32 (-16..16), not Q3's 30x30.
 * Presence types: Gladiator 4=NORMAL, 2=CROUCH (Q3 uses 1/2, same values). */
int __cdecl AAS_PresenceTypeBoundingBox(int presencetype, vec3_t mins, vec3_t maxs)
{
  int    index;
  vec3_t boxmins[3] = { {0.0f, 0.0f, 0.0f}, {-16.0f, -16.0f, -24.0f}, {-16.0f, -16.0f, -24.0f} };
  vec3_t boxmaxs[3] = { {0.0f, 0.0f, 0.0f}, { 16.0f,  16.0f,  32.0f}, { 16.0f,  16.0f,   8.0f} };

  if ( presencetype == 4 )
    index = 1;
  else
  {
    if ( presencetype != 2 )
      botimport.Print(PRT_FATAL,
               "AAS_PresenceTypeBoundingBox: unknown presence type\n");
    index = 2;
  }
  VectorCopy(boxmins[index], mins);
  VectorCopy(boxmaxs[index], maxs);
  /* Gladiator returns the raw float bits of maxs[2] in eax (asm leaves them
   * there as a side effect of the last store).  Q3 returns void. */
  return *(int *)&maxs[2];
}

