//----- (1000EEB0) --------------------------------------------------------
BOOL __cdecl AAS_OnGround(vec3_t origin, int presencetype, int passent)
{
  aas_trace_t trace;
  vec3_t end;
  aas_plane_t *plane;
  float steepness;

  VectorCopy(origin, end);
  end[2] -= 4.0f;

  trace = AAS_TraceClientBBox(origin, end, presencetype, passent);

  if ( trace.startsolid ) return 0;
  if ( trace.fraction >= 1.0 ) return 0;
  if ( origin[2] - trace.endpos[2] > 2.0f ) return 0;
  plane = (aas_plane_t *)AAS_PlaneFromNum(trace.planenum);
  steepness = plane->normal[2];
  if ( steepness < libvar_sv_maxsteepness->value ) return 0;
  return 1;
}

//----- (1000EFC0) --------------------------------------------------------
/* function actually tests if a point 2 units below the
 * given origin is in liquid (LAVA|SLIME|WATER = 0x38).  Used by BotMoveInDirection
 * to pick a swim/jump movement style.  IDA dropped the bi_PointContents call
 * (compare 0x1000efe6 in the binary) and v3 was uninitialized. */
BOOL __cdecl AAS_Swimming(vec3_t origin)
{
  /* v5 must be int[3]: the X/Y stores are raw 32-bit copies (not int->float
   * conversions), preserving the float bit pattern from origin.  Verified at
   * .text 0x1000efc0: mov [esp+0],ecx / mov [esp+8],edx for X/Y, and
   * fstp [esp+0xc] for Z.  Retyping to float[3] silently injects a
   * cvtsi2ss on the first two stores, garbling X/Y of the test point and
   * making bi_PointContents always miss water — bots in water never enter
   * the swim branch and get stuck. */
  int testorg[3]; // [esp+0h] [ebp-Ch] BYREF
  float z; // st7

  z = ((float *)origin)[2];
  testorg[0] = *(_DWORD *)origin;
  testorg[1] = *(_DWORD *)((char *)origin + 4);
  *(float *)&testorg[2] = z - 2.0f;
  return (sub_10003080((float *)testorg) & 0x38) != 0;
}

//----- (1000F010) --------------------------------------------------------
/*
 * AAS_JumpReachRunStart — compute the run-up start position for a TRAVEL_JUMP
 * reachability: predict the bot's movement back from reach->start along the
 * horizontal direction (start - end), scale-400, and write the predicted
 * endpos into `runstart`.  Falls back to `start` if the prediction hits
 * water/slime/lava or a ground-damage drop (stopevent mask 0x38 | 0x04 = 0x3C
 * is what Q3 uses; the captured mask test here is `v8 & 0x38`).
 *
 * Renamed from sub_1000F010 / AAS_PredictMoveDir.
 * Structural match: ioq3 code/botlib/be_aas_move.c:256.
 */
void __cdecl AAS_JumpReachRunStart(aas_reachability_t* reach, intptr_t runstart)
{
  float *runstart_vec; // edi
  char stopevent; // cl
  /* IDA split a vec3 stack local (origin+1z) into three adjacent locals
   * v11/v12/v13 at [ebp-74h]/[ebp-70h]/[ebp-6Ch]; passed as a vec3 via
   * &v11 to AAS_ClientMovementPrediction.  GCC will not preserve that adjacency
   * (verified: v11 at esp+0xb4, v12 at esp+0xd0 — 28-byte gap), so the
   * callee reads junk for start[1]/start[2].  Collapse into a proper
   * vec3_t to guarantee contiguous layout. */
  vec3_t start_pos; // [esp+8h] [ebp-74h] BYREF (was v11/v12/v13)
  vec3_t hordir; // [esp+14h] [ebp-68h] BYREF
  vec3_t cmdmove; // [esp+20h] [ebp-5Ch] BYREF
  aas_clientmove_t move; // [esp+2Ch] [ebp-50h] BYREF (coalesced with the by-value return temp)

  hordir[0] = reach->start[0] - reach->end[0];
  hordir[1] = reach->start[1] - reach->end[1];
  hordir[2] = 0;
  VectorNormalize(hordir);
  start_pos[0] = reach->start[0];
  start_pos[1] = reach->start[1];
  start_pos[2] = reach->start[2] + 1.0f;
  runstart_vec = (float *)runstart;
  VectorScale((float *)hordir, 400.0f, (float *)cmdmove);
  move = AAS_ClientMovementPrediction(-1, start_pos, 2, 1, velocity, cmdmove, 1, 2, 0.1f, 124, 0);
  VectorCopy(move.endpos, runstart_vec);
  stopevent = move.stopevent;
  if ( (stopevent & 0x38) != 0 )
  {
    VectorCopy(start_pos, runstart_vec);
  }
}

//----- (1000F130) --------------------------------------------------------
// Probes the engine's PointContents() at six positions around a 3D
// origin, looking for the high-bit-29 content flag (0x20000000 —
// Gladiator's "do-not-enter / bot-area-block" overlay).  The probes
// trace a 16x16 box at the eye-height offset (+48 on Z) plus the
// floor point itself:
//   (x,   y,   z+48)
//   (x+8, y+8, z+48)
//   (x-8, y+8, z+48)
//   (x-8, y-8, z+48)
//   (x+8, y-8, z+48)
//   (x,   y,   z)
// The first five take the early-exit "return 1" path on a hit; the
// floor probe returns the bit as 0/1 directly via shr 29 / and 1.
// Constants from .rdata 0x100580dc/e0/e4 = 16.0f / 8.0f / 48.0f.
// DEAD in Gladiator — /INCREMENTAL.  Restored from objdump@1000F130.
//----- (10003080) --- thin wrapper forwarding to bi_PointContents
int __cdecl sub_10003080(vec3_t point)
{
  return botimport.PointContents(point);
}

int __cdecl sub_1000F130(vec3_t origin)
{
  vec3_t p;

  p[0] = origin[0];
  p[1] = origin[1];
  p[2] = origin[2] + 48.0f;
  if ( sub_10003080(p) & 0x20000000 ) return 1;
  p[0] += 8.0f;
  p[1] += 8.0f;
  if ( sub_10003080(p) & 0x20000000 ) return 1;
  p[0] -= 16.0f;
  if ( sub_10003080(p) & 0x20000000 ) return 1;
  p[1] -= 16.0f;
  if ( sub_10003080(p) & 0x20000000 ) return 1;
  p[0] += 16.0f;
  if ( sub_10003080(p) & 0x20000000 ) return 1;
  p[0] -= 8.0f;
  p[1] += 8.0f;
  p[2] -= 48.0f;
  return ((unsigned)sub_10003080(p) >> 29) & 1;
}

//----- (1000F2C0) --------------------------------------------------------
int __cdecl AAS_AgainstLadder(vec3_t origin)
{
  int areanum; // eax
  int i; // ebx
  int facenum; // esi
  int side;
  vec3_t org;
  aas_plane_t *plane;
  aas_face_t *face; // eax
  aas_area_t *area; // ebp

  VectorCopy(origin, org);
  areanum = AAS_PointAreaNum(org);
  if ( !areanum )
  {
    org[0] += 1;
    areanum = AAS_PointAreaNum(org);
    if ( !areanum )
    {
      org[1] += 1;
      areanum = AAS_PointAreaNum(org);
      if ( !areanum )
      {
        org[0] -= 2;
        areanum = AAS_PointAreaNum(org);
        if ( !areanum )
        {
          org[1] -= 2;
          areanum = AAS_PointAreaNum(org);
        }
      }
    }
  }
  if ( !areanum ) return 0;
  if ( !(aasworld.areasettings[areanum].areaflags & 2)) return 0;
  if ( !(aasworld.areasettings[areanum].presencetype & 2)) return 0;

  area = &aasworld.areas[areanum];
  for (i = 0; i < area->numfaces; i++)
  {
    facenum = aasworld.faceindex[area->firstface + i];
    side = facenum < 0;
    face = &aasworld.faces[abs(facenum)];
    if (!(face->faceflags & 2)) continue;
    plane = &aasworld.planes[face->planenum ^ side];
    if (abs(DotProduct(plane->normal, origin) - plane->dist) < 3)
    {
      if (AAS_PointInsideFace(abs(facenum), origin, 0.1f)) return 1;
    }
  }
  return 0;
}

//----- (1000F4D0) --------------------------------------------------------
double __cdecl AAS_WeaponJumpZVelocity(vec3_t origin, float radiusdamage)
{
  vec3_t kvel, v, start, end, forward, right, viewangles, dir;
  float mass, knockback, points;
  vec3_t rocketoffset = {8, 8, -8};
  vec3_t botmins = {-16, -16, -24};
  vec3_t botmaxs = {16, 16, 32};
  bsp_trace_t bsptrace;

  viewangles[PITCH] = 90.0f;
  viewangles[YAW] = 0.0f;
  viewangles[ROLL] = 0.0f;

  VectorCopy(origin, start);
  start[2] += 8.0f;
  AngleVectors(viewangles, forward, right, NULL);
  start[0] += forward[0] * rocketoffset[0] + right[0] * rocketoffset[1];
  start[1] += forward[1] * rocketoffset[0] + right[1] * rocketoffset[1];
  start[2] += forward[2] * rocketoffset[0] + right[2] * rocketoffset[1] + rocketoffset[2];

  VectorMA(start, 500.0, forward, end);
  bsptrace = AAS_Trace(start, NULL, NULL, end, 1, 3);

  VectorAdd(botmins, botmaxs, v);
  VectorMA(origin, 0.5, v, v);
  VectorSubtract(bsptrace.endpos, v, v);

  points = radiusdamage - 0.5 * VectorLength(v);
  if ( points < 0.0f )
    points = 0.0f;
  points *= 0.5;

  mass = 200.0f;
  knockback = points;
  VectorSubtract(origin, bsptrace.endpos, dir);
  VectorNormalize(dir);
  VectorScale(dir, 1600.0 * (float)knockback / mass, kvel);
  return kvel[2] + libvar_sv_jumpvel->value;
}

//----- (1000F750) --------------------------------------------------------
/*
 * AAS_RocketJumpZVelocity — Z-velocity gained by self-rocketing at `origin`
 * with the rocket-launcher's 120-unit radius damage.  Renamed from
 * sub_1000F750 / AAS_FallVelocity; one-line wrapper around the underlying
 * AAS_WeaponJumpZVelocity (currently still named AAS_WeaponJumpZVelocity at
 * 0x1000F4D0; rename pending).  Matches ioq3 be_aas_move.c:341.
 */
float __cdecl AAS_RocketJumpZVelocity(vec3_t origin)
{
  return AAS_WeaponJumpZVelocity(origin, 120.0);
}

//----- (1000F780) --------------------------------------------------------
double __cdecl AAS_BFGJumpZVelocity(vec3_t origin)
{
  return AAS_WeaponJumpZVelocity(origin, 120.0);
}

//----- (1000F7B0) --------------------------------------------------------
void __cdecl AAS_ApplyFriction(vec3_t vel, float friction, float stopspeed, float frametime)
{
  float speed; // st5
  float control; // st6
  float newspeed; // st6

  speed = sqrt(vel[0] * vel[0] + vel[1] * vel[1]);
  if ( speed != 0.0f )
  {
    if ( speed < stopspeed )
      control = stopspeed;
    else
      control = speed;
    newspeed = speed - control * friction * frametime;
    if ( newspeed < 0.0f )
      newspeed = 0.0f;
    vel[0] = newspeed / speed * vel[0];
    vel[1] = newspeed / speed * vel[1];
  }
}

