  vec3_t maxs; // [esp+2Ch] [ebp-188h] BYREF
  vec3_t dir; // [esp+38h] [ebp-17Ch] BYREF
  vec3_t right; // [esp+44h] [ebp-170h] BYREF
  vec3_t mins; // [esp+50h] [ebp-164h] BYREF
  vec3_t end; // [esp+5Ch] [ebp-158h] BYREF
