double __cdecl AngleDiff(float ang1, float ang2)
{
  double result; // st7

  result = ang1 - ang2;
  if ( ang1 > ang2 )
  {
    if ( result > 180.0 )
      return result - 360.0;
  }
  else if ( result < -180.0 )
  {
    return result + 360.0;
  }
  return result;
}

