int __cdecl PC_OperatorPriority(int op)
{
  int result; // eax

  switch ( op )
  {
    case 5:
      result = 7;
      break;
    case 6:
      result = 6;
      break;
    case 9:
    case 10:
      result = 11;
      break;
    case 7:
    case 8:
    case 37:
    case 38:
      result = 12;
      break;
    case 21:
    case 22:
      result = 13;
      break;
    case 26:
    case 27:
    case 28:
      result = 15;
      break;
    case 29:
    case 30:
      result = 14;
      break;
    case 32:
      result = 10;
      break;
    case 33:
      result = 8;
      break;
    case 34:
      result = 9;
      break;
    case 35:
    case 36:
      result = 16;
      break;
    case 42:
    case 43:
      result = 5;
      break;
    default:
      result = 0;
      break;
  }
  return result;
}

