int __cdecl PS_ReadEscapeCharacter(script_t *script, _BYTE *ch)
{
  int c, val, i;

  script->script_p++;
  switch ( *script->script_p )
  {
    case '\\':
      c = '\\';
      break;
    case 'n':
      c = '\n';
      break;
    case 'r':
      c = '\r';
      break;
    case 't':
      c = '\t';
      break;
    case 'v':
      c = '\v';
      break;
    case 'b':
      c = '\b';
      break;
    case 'f':
      c = '\f';
      break;
    case 'a':
      c = '\a';
      break;
    case '\'':
      c = '\'';
      break;
    case '"':
      c = '"';
      break;
    case '?':
      c = '?';
      break;
    case 'x':
    {
      script->script_p++;
      for ( i = 0, val = 0; ; i++, script->script_p++ )
      {
        c = *script->script_p;
        if ( c >= '0' && c <= '9' ) c = c - '0';
        else if ( c >= 'A' && c <= 'Z' ) c = c - 'A' + 10;
        else if ( c >= 'a' && c <= 'z' ) c = c - 'a' + 10;
        else break;
        val = (val << 4) + c;
      }
      script->script_p--;
      if ( val > 0xFF )
      {
        ScriptWarning(script, "too large value in escape character");
        val = 0xFF;
      }
      c = val;
      break;
    }
    default:
    {
      if ( *script->script_p < '0' || *script->script_p > '9' )
        ScriptError(script, "unknown escape char");
      for ( i = 0, val = 0; ; i++, script->script_p++ )
      {
        c = *script->script_p;
        if ( c >= '0' && c <= '9' ) c = c - '0';
        else break;
        val = val * 10 + c;
      }
      script->script_p--;
      if ( val > 0xFF )
      {
        ScriptWarning(script, "too large value in escape character");
        val = 0xFF;
      }
      c = val;
      break;
    }
  }
  script->script_p++;
  *ch = c;
  return 1;
}

//----- (1003E7F0) --------------------------------------------------------
int __cdecl PS_ReadString(script_t *script, token_t *token, int quote)
{
  int len;
  int tmpline;
  char *tmpscript_p;

  if ( quote == 34 )
    token->type = 1;
  else
    token->type = 2;
  len = 0;
  token->string[len++] = *script->script_p++;
  while ( 1 )
  {
    if ( len >= 1022 )
    {
      ScriptError(script, "string longer than MAX_TOKEN = %d", 1024);
      return 0;
    }
    if ( *script->script_p == 92 && (script->flags & 8) == 0 )
    {
      if ( !PS_ReadEscapeCharacter(script, &token->string[len]) )
      {
        token->string[len] = 0;
        return 0;
      }
      len++;
    }
    else if ( *script->script_p == quote )
    {
      ++script->script_p;
      if ( (script->flags & 4) != 0 )
        break;
      tmpscript_p = script->script_p;
      tmpline = script->line;
      if ( !PS_ReadWhiteSpace(script) )
      {
        script->script_p = tmpscript_p;
        script->line = tmpline;
        break;
      }
      if ( *script->script_p != quote )
      {
        script->script_p = tmpscript_p;
        script->line = tmpline;
        break;
      }
      ++script->script_p;
    }
    else
    {
      if ( !*script->script_p )
      {
        token->string[len] = 0;
        ScriptError(script, "missing trailing quote");
        return 0;
      }
      if ( *script->script_p == 10 )
      {
        token->string[len] = 0;
        ScriptError(script, "newline inside string %s", token->string);
        return 0;
      }
      token->string[len++] = *script->script_p++;
    }
  }
  token->string[len++] = quote;
  token->string[len] = 0;
  token->subtype = len;
  return 1;
}

//----- (1003E9F0) --------------------------------------------------------
int __cdecl PS_ReadName(script_t *script, intptr_t a2)
{
  token_t *token = (token_t *)a2;
  int len = 0;
  char c; // al

  token->type = 4;
  do
  {
    token->string[len++] = *script->script_p++;
    if ( len >= 1024 )
    {
      ScriptError(script, "name longer than MAX_TOKEN = %d", 1024);
      return 0;
    }
    c = *script->script_p;
  }
  while ( (c >= 97 && c <= 122) || (c >= 65 && c <= 90) || (c >= 48 && c <= 57) || c == 95 );
  token->string[len] = 0;
  token->subtype = len;
  return 1;
}

//----- (1003EAB0) --------------------------------------------------------
/* Original gladiator helper at 0x1003EAB0.  The IDA decompile expressed
 * the moving cursor through `a1` using HIDWORD(v4) — i.e. it stuffed a
 * 32-bit pointer into the upper half of a 64-bit register.  That idiom
 * is meaningless on 64-bit (real pointers don't fit in 32 bits), so the
 * body is restored to walk `a1` via a normal `char *p` local.  Control
 * flow, arithmetic, and disassembled instruction order are preserved 1:1.
 * Subtype flags match the original: 0x800=float 0x8=decimal 0x100=hex
 * 0x200=octal 0x400=binary. */
void __cdecl NumberValue(char *string, int subtype, int *intvalue, double *floatvalue)
{
  char *p;
  unsigned int dotfound = 0;
  char i;

  *intvalue = 0;
  *floatvalue = 0.0;
  if ( (subtype & 0x800) != 0 )
  {
    for ( p = string; (i = *p) != 0; ++p )
    {
      if ( i == 46 )
      {
        if ( dotfound )
          return;
        dotfound = 10;
        ++p;
      }
      if ( dotfound )
      {
        *floatvalue = (double)((*p) - 48) / (double)dotfound + *floatvalue;
        dotfound *= 10;
      }
      else
      {
        *floatvalue = (double)(i - 48) + *floatvalue * 10.0;
      }
    }
    *intvalue = (int)*floatvalue;
  }
  else if ( (subtype & 8) != 0 )
  {
    for ( p = string; *p; ++p )
      *intvalue = *p + 10 * *intvalue - 48;
    *floatvalue = (double)(unsigned int)*intvalue;
  }
  else if ( (subtype & 0x100) != 0 )
  {
    string += 2;
    while ( *string )
    {
      *intvalue <<= 4;
      if ( *string >= 'a' && *string <= 'f' )
        *intvalue += *string - 'a' + 10;
      else if ( *string >= 'A' && *string <= 'F' )
        *intvalue += *string - 'A' + 10;
      else
        *intvalue += *string - '0';
      ++string;
    }
    *floatvalue = (double)(unsigned int)*intvalue;
  }
  else if ( (subtype & 0x200) != 0 )
  {
    ++string;
    while ( *string )
      *intvalue = (*intvalue << 3) + (*string++ - '0');
    *floatvalue = (double)(unsigned int)*intvalue;
  }
  else if ( (subtype & 0x400) != 0 )
  {
    for ( p = string + 2; *p; ++p )
      *intvalue = *p + 2 * *intvalue - 48;
    *floatvalue = (double)(unsigned int)*intvalue;
  }
}

//----- (1003ECD0) --------------------------------------------------------
int __cdecl PS_ReadNumber(script_t *script, token_t *token)
{
  int len = 0;
  char c;
  int octal, dot;
  int i;

  token->type = 3;
  if ( *script->script_p == 48 && (script->script_p[1] == 120 || script->script_p[1] == 88) )
  {
    token->string[len++] = *script->script_p++;
    token->string[len++] = *script->script_p++;
    c = *script->script_p;
    /* hexadecimal — NB the faithful Gladiator quirk: uppercase digits admit only 'A' (65..65) */
    while ( (c >= 48 && c <= 57) || (c >= 97 && c <= 102) || (c >= 65 && c <= 65) )
    {
      token->string[len++] = c;
      if ( len >= 1024 )
      {
        ScriptError(script, "hexadecimal number longer than MAX_TOKEN = %d",
                    1024);
        return 0;
      }
      c = *++script->script_p;
    }
    token->subtype |= 0x100;
  }
  else if ( *script->script_p == 48 && (script->script_p[1] == 98 || script->script_p[1] == 66) )
  {
    token->string[len++] = *script->script_p++;
    token->string[len++] = *script->script_p++;
    c = *script->script_p;
    while ( c == 48 || c == 49 )
    {
      token->string[len++] = c;
      if ( len >= 1024 )
      {
        ScriptError(script, "binary number longer than MAX_TOKEN = %d", 1024);
        return 0;
      }
      c = *++script->script_p;
    }
    token->subtype |= 0x400;
  }
  else
  {
    octal = 0;
    dot = 0;
    if ( *script->script_p == 48 )
      octal = 1;
    while ( 1 )
    {
      token->string[len++] = *script->script_p++;
      if ( len >= 1024 )
      {
        ScriptError(script, "number longer than MAX_TOKEN = %d", 1024);
        return 0;
      }
      c = *script->script_p;
      if ( c == 46 )
        dot = 1;
      else if ( c == 56 || c == 57 )
        octal = 0;
      else if ( c < 48 || c > 57 )
        break;
    }
    if ( octal )
      token->subtype |= 0x200;
    else
      token->subtype |= 8;
    if ( dot )
      token->subtype |= 0x800;
  }
  for ( i = 0; i < 2; i++ )
  {
    c = *script->script_p;
    if ( c == 108 || c == 76 && (token->subtype & 0x2000) == 0 )
    {
      script->script_p++;
      token->subtype |= 0x2000;
    }
    else if ( c == 117 || c == 85 && (token->subtype & 0x4800) == 0 )
    {
      script->script_p++;
      token->subtype |= 0x4000;
    }
  }
  token->string[len] = 0;
  NumberValue(token->string, token->subtype, (int *)&token->intvalue, &token->floatvalue);
  if ( (token->subtype & 0x800) == 0 )
    token->subtype |= 0x1000;
  return 1;
}
