int __cdecl WriteFloat(FILE *fp, float value)
{
  char buf[128];
  int l;

  sprintf(buf, "%f", value);
  l = strlen(buf);
  while ( l-- > 1 )
  {
    if ( buf[l] != '0' && buf[l] != '.' ) break;
    if ( buf[l] == '.' )
    {
      buf[l] = 0;
      break;
    }
    buf[l] = 0;
  }
  return fprintf(fp, "%s", buf) >= 0;
}

